const charactersBeforeReferenceSync=characters;
characters=function(){charactersBeforeReferenceSync();const c=data.characters[ci];if(!c||c.view!=='multi')return;const current=selectedFront(c),confirmed=c.confirmed&&c.confirmedVersion===c.active,entry=activeMulti(c);const boxes=document.querySelectorAll('#panel .angle-grid .angle');const frontCaption=boxes[1]?.querySelector('span');if(frontCaption)frontCaption.textContent=confirmed?'当前已确认正面':'当前正面 · 请先确认';let staleCount=0;for(const [index,angle] of ['portrait','left','back'].entries()){const box=boxes[[0,2,3][index]];if(!box)continue;const job=entry?.jobs?.[angle],source=job?.reference_job_id||entry?.reference_job_id;const stale=job&&!job.identity_master&&current?.job_id&&source!==current.job_id;if(stale){staleCount++;const warning=document.createElement('p');warning.className='subtle';warning.style.cssText='color:#e9bd87;margin:6px 8px';warning.textContent='使用旧正面图 · 此角度待更新';box.append(warning)}const button=box.querySelector('button');if(button&&!confirmed){button.disabled=true;button.title='请先确认当前正面图';}}if(!confirmed||staleCount){const note=document.createElement('p');note.className='subtle';note.style.cssText='color:#e9bd87;margin:10px 0';note.textContent=!confirmed?'正面图已更换：请确认当前正面图后，再重新生成其他角度。':'正面图已更新，'+staleCount+' 个旧角度保留供对比，可分别重新生成或重做整组。';document.querySelector('#panel .artboard')?.after(note)}};
render();
